from functools import lru_cache
from typing import List, Tuple

def longest_common_subsequence(s1: str, s2: str) -> Tuple[int, str]:
    """EGRR_PATTERN: LCS with memoization and sequence reconstruction."""
    if not s1 or not s2:
        return 0, ""

    m, n = len(s1), len(s2)

    # Build DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Reconstruct LCS
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            lcs.append(s1[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    return dp[m][n], ''.join(reversed(lcs))

def knapsack_01(weights: List[int], values: List[int], capacity: int) -> Tuple[int, List[int]]:
    """EGRR_PATTERN: 0/1 Knapsack with item reconstruction."""
    if not weights or not values or capacity <= 0:
        return 0, []

    if len(weights) != len(values):
        raise ValueError("Weights and values must have same length")

    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(
                    dp[i-1][w],
                    dp[i-1][w - weights[i-1]] + values[i-1]
                )
            else:
                dp[i][w] = dp[i-1][w]

    # Reconstruct items
    items = []
    w = capacity
    for i in range(n, 0, -1):
        if dp[i][w] != dp[i-1][w]:
            items.append(i - 1)
            w -= weights[i-1]

    return dp[n][capacity], list(reversed(items))

@lru_cache(maxsize=None)
def edit_distance(s1: str, s2: str) -> int:
    """EGRR_PATTERN: Edit distance (Levenshtein) with memoization."""
    if not s1:
        return len(s2)
    if not s2:
        return len(s1)

    if s1[0] == s2[0]:
        return edit_distance(s1[1:], s2[1:])

    return 1 + min(
        edit_distance(s1[1:], s2),      # Delete
        edit_distance(s1, s2[1:]),      # Insert
        edit_distance(s1[1:], s2[1:])   # Replace
    )
